<template>
  <view class="screen" :class="{ 'has-player': !!currentTrack }">
    <view class="topbar">
      <view class="brand-mark"><text>≈</text></view><view class="brand-name">雾屿</view>
      <view class="top-spacer"></view>
      <button class="top-icon-button" aria-label="音乐库管理" @tap="sheet = 'settings'"><image src="/static/icons/more.svg" mode="aspectFit" /></button>
    </view>
    <view v-if="importStatus" class="status-banner" role="status"><text>{{ importStatus }}</text><view v-if="importBusy" class="import-progress-row"><text>本首 {{ importFilePercent }}% · 总体 {{ importPercent }}%<br />本批 {{ importElapsed }} 秒 · 本首 {{ importFileElapsed }} 秒<br />进度按处理阶段更新</text><button :disabled="importCancelled" @tap="cancelImport">{{ importCancelled ? '正在取消…' : '取消导入' }}</button></view><progress v-if="importBusy || backupBusy" :percent="importBusy ? importPercent : backupProgress" activeColor="#5d896c" backgroundColor="#dce8df" :stroke-width="3" /></view>
    <view v-if="metadataStatus && !importBusy" class="metadata-banner" role="status">{{ metadataStatus }} · 歌曲已可播放</view>
    <view v-if="lastError" class="error-banner" role="alert"><text>{{ lastError }}</text><button @tap="ready ? playTrack(currentTrack, true) : initialize()">重试</button><button aria-label="关闭错误提示" @tap="lastError = ''">关闭</button></view>
    <scroll-view class="page-scroll" scroll-y :show-scrollbar="false" @scroll="pageScrollTop = $event.detail.scrollTop">
      <view v-if="activeTab === 'discover'" class="page-content">
        <view class="hero glass-card">
          <view class="hero-copy"><text class="hero-title">把喜欢的歌，<br />带来这里。</text><text class="hero-subtitle">封面、歌词与每一个喜欢的瞬间。</text>
            <button class="primary-button" :loading="importBusy" :disabled="importBusy || backupBusy || !ready" @tap="importSong"><view class="button-icon"><image src="/static/icons/add.svg" mode="aspectFit" /></view><text>{{ importBusy ? '正在导入' : '导入本地歌曲' }}</text></button>
          </view><view class="hero-record"><view class="record-label"></view></view>
        </view>
        <view class="section-heading"><view><text class="section-title">最近加入</text><text class="section-subtitle">只保存在你的设备上</text></view><button class="text-button" @tap="activeTab = 'library'">查看全部</button></view>
        <TrackList :tracks="tracks.slice(-4).reverse()" :current-id="currentId" @select="selectTrack" @menu="showTrackMenu" />
        <view v-if="!tracks.length" class="empty-card glass-card"><text class="empty-title">你的第一首歌，从这里开始</text><text class="empty-copy">支持一次选择多首歌曲，自动识别封面和歌词。</text><button class="secondary-button" :disabled="importBusy || !ready" @tap="importSong">选择歌曲</button></view>
      </view>
      <view v-else-if="activeTab === 'search'" class="page-content">
        <view class="page-heading"><text class="page-title">搜索你的音乐</text><text class="page-subtitle">按歌名、歌手或专辑查找。</text></view>
        <view class="search-box glass-card"><image src="/static/icons/search.svg" mode="aspectFit" /><input v-model="query" placeholder="搜索歌曲、歌手或专辑" confirm-type="search" /></view>
        <view class="section-heading compact-heading"><text class="section-title">{{ query ? '搜索结果' : '全部歌曲' }}</text><text class="track-artist">{{ visibleTracks.length }} 首</text></view>
        <TrackList :tracks="visibleTracks" :current-id="currentId" :scroll-top="pageScrollTop" :viewport-top="viewportTop" :viewport-height="viewportHeight" @select="selectTrack" @menu="showTrackMenu" />
        <view v-if="!visibleTracks.length" class="empty-card glass-card small-empty"><text class="empty-title">没有找到歌曲</text><text class="empty-copy">试试其他歌名或歌手。</text></view>
      </view>
      <view v-else class="page-content">
        <view class="library-banner glass-card"><view><text class="page-title">我的音乐</text><text class="page-subtitle">{{ tracks.length }} 首歌曲 · 私人收藏</text></view><button class="primary-button small-primary" :disabled="importBusy || backupBusy || !ready" @tap="importSong"><image src="/static/icons/add.svg" mode="aspectFit" />导入</button></view>
        <view class="filter-tabs"><button v-for="filter in filters" :key="filter.id" :class="{ selected: libraryFilter === filter.id }" @tap="setFilter(filter.id)">{{ filter.label }}</button></view>
        <view v-if="['albums', 'artists', 'playlists'].includes(libraryFilter) && !groupFilter">
          <view class="section-heading compact-heading"><text class="section-title">{{ filters.find(item => item.id === libraryFilter).label }}</text><button v-if="libraryFilter === 'playlists'" class="text-button" @tap="sheet = 'new-playlist'">新建歌单</button></view>
          <button v-for="group in libraryGroups" :key="group.id" class="group-card glass-card" @tap="groupFilter = group.id"><text>{{ group.name }}</text><text class="track-artist">{{ group.count }} 首</text></button>
          <text v-if="!libraryGroups.length" class="empty-copy empty-inline">还没有歌单，创建一个收藏喜欢的歌曲吧。</text>
        </view>
        <view v-else>
          <view class="section-heading compact-heading"><button v-if="groupFilter" class="text-button" @tap="endSelection(); groupFilter = ''">返回分类</button><text class="section-title">{{ groupFilter ? libraryGroups.find(group => group.id === groupFilter)?.name : libraryFilter === 'favorites' ? '我喜欢的' : '所有歌曲' }}</text><button v-if="libraryFilter === 'playlists' && groupFilter" class="text-button danger" @tap="deletePlaylist">删除歌单</button></view>
          <view class="library-tools">
            <button class="text-button" @tap="selecting ? endSelection() : selecting = true">{{ selecting ? '完成多选' : '多选管理' }}</button>
            <button v-if="libraryFilter === 'playlists' && groupFilter" class="text-button" @tap="playlistEditName = libraryGroups.find(group => group.id === groupFilter)?.name || ''; sheet = 'rename-playlist'">重命名歌单</button>
          </view>
          <view v-if="selecting" class="selection-toolbar glass-card"><text>已选 {{ selectedIds.length }} 首</text><button @tap="selectAllTracks">全选 / 取消</button><button :disabled="!selectedIds.length" @tap="batchFavorite">喜欢</button><button :disabled="!selectedIds.length" @tap="sheet = 'add-playlist'">加入歌单</button><button :disabled="!selectedIds.length" class="danger" @tap="removeSelected">移除</button></view>
          <TrackList :selecting="selecting" :selected-ids="selectedIds" :tracks="libraryTracks" :current-id="currentId" :scroll-top="pageScrollTop" :viewport-top="viewportTop" :viewport-height="viewportHeight" @select="selectTrack" @menu="showTrackMenu" />
          <text v-if="!libraryTracks.length" class="empty-copy empty-inline">这里还没有歌曲。</text>
        </view>
      </view>
    </scroll-view>
    <view v-if="currentTrack" class="mini-player glass-card">
      <view class="mini-progress"><view :style="{ width: progress + '%' }"></view></view>
      <button class="mini-main" aria-label="打开播放页" @tap="playerOpen = true"><image v-if="currentTrack.cover" class="mini-cover" :src="currentTrack.cover" mode="aspectFill" /><view v-else class="mini-cover cover-fallback">♫</view><view class="mini-copy"><text class="track-title">{{ currentTrack.title }}</text><text class="track-artist">{{ currentTrack.artist || '未知歌手' }}</text></view></button>
      <button class="transport-button" aria-label="上一首" @tap="playAdjacent(-1)"><image src="/static/icons/previous.svg" mode="aspectFit" /></button>
      <button class="mini-play" :loading="loading" :aria-label="isPlaying ? '暂停' : '播放'" @tap="togglePlayback"><image v-if="!loading" :src="isPlaying ? '/static/icons/pause.svg' : '/static/icons/play.svg'" mode="aspectFit" /></button>
      <button class="transport-button" aria-label="下一首" @tap="playAdjacent(1)"><image src="/static/icons/next.svg" mode="aspectFit" /></button>
    </view>
    <view class="bottom-nav glass-card">
      <button v-for="tab in tabs" :key="tab.id" class="nav-item" :class="{ active: activeTab === tab.id }" :aria-label="tab.label" @tap="activeTab = tab.id"><image :src="tab.icon" mode="aspectFit" /><text>{{ tab.label }}</text></button>
    </view>
    <view v-if="currentTrack" v-show="playerOpen" class="player-overlay">
      <view class="player-sheet" :class="{ immersive: immersive, 'listening-mode': listeningDisplay }">
        <view class="player-scene" :class="{ 'scene-cover': playerView === 'cover' }">
        <ParticleCover ref="particleRef" @immersive="enterImmersive" :immersive="immersive || listeningDisplay" :display-mode="listeningDisplay" @display="enterListeningDisplay" @scene-tap="handleSceneTap" :cover="currentTrack.cover" :cover-key="currentTrack.coverKey || currentTrack.cover" :audio="currentTrack.uri" :audio-key="currentTrack.audioKey" :size="currentTrack.size || 0" :time="currentTime" :playing="isPlaying" :visible="appForeground && playerOpen && playerView === 'cover'" />
        <ListeningDisplay v-if="listeningDisplay" ref="listeningDisplayRef" :active="appForeground && playerOpen" :title="currentTrack.title" :artist="currentTrack.artist" :playing="isPlaying" :loading="loading" @close="listeningDisplay = false" @previous="playAdjacent(-1)" @next="playAdjacent(1)" @toggle="togglePlayback" />
        <button v-if="immersive && immersiveExitVisible" class="immersive-exit" @tap="immersive = false">退出沉浸</button><view class="player-top"><button class="top-icon-button" aria-label="关闭播放器" @tap="playerOpen = false"><image src="/static/icons/down.svg" mode="aspectFit" /></button><view class="view-switch"><button :class="{ selected: playerView === 'cover' }" @tap="playerView = 'cover'">封面</button><button :class="{ selected: playerView === 'lyrics' }" @tap="playerView = 'lyrics'">歌词</button></view><view class="player-top-actions"><button class="top-icon-button" aria-label="当前歌曲操作" @tap="showTrackMenu(currentTrack)"><image src="/static/icons/more.svg" mode="aspectFit" /></button></view></view>
        <view class="player-content" :class="{ 'is-swiping': playerSwiping }" @touchstart="beginPlayerSwipe" @touchmove="movePlayerSwipe" @touchend="endPlayerSwipe" @touchcancel="cancelPlayerSwipe">
          <view class="player-panels" :style="playerPanelStyle">
          <view class="player-pane" :aria-hidden="playerView !== 'cover'">
          </view>
          <view class="player-pane" :aria-hidden="playerView !== 'lyrics'">
          <view class="lyrics-view">
            <view v-if="!followLyrics" class="lyrics-heading"><view class="lyric-action-hit" @tap="followLyrics = true"><button class="lyric-action-button" @tap.stop="followLyrics = true">回到当前歌词</button></view></view>
            <view class="lyrics-online-bar"><text>{{ lyricFetching.includes(currentId) ? '正在匹配同步歌词…' : currentTrack.lyrics.length ? '' : currentTrack.lyricLookup || '' }}</text><view class="lyric-action-hit" @tap="activateLyricAction"><button class="lyric-action-button" @tap.stop="activateLyricAction">{{ lyricRetryable && !lyricFetching.includes(currentId) ? '重试获取' : '联网找歌词' }}</button></view></view>
            <LyricsLines v-if="currentTrack.lyrics.length" :key="currentId" :lines="currentTrack.lyrics" :active-index="activeLyric" :visible="playerOpen && playerView === 'lyrics'" v-model:follow="followLyrics" @seek="seekLyric" />
            <view v-else class="no-lyrics"><text>还没有歌词</text><button class="secondary-button" @tap="importLyrics">导入歌词文件</button></view>
            <view class="lyric-offset"><button @tap="adjustOffset(-0.5)">提前 0.5 秒</button><button aria-label="重置歌词时间偏移" @tap="adjustOffset(-(currentTrack.lyricOffset || 0))">{{ (currentTrack.lyricOffset || 0).toFixed(1) }} 秒 · 重置</button><button @tap="adjustOffset(0.5)">延后 0.5 秒</button></view>
          </view>
          </view>
          </view>
        </view>
        <view v-if="playerView === 'cover'" class="player-edge-swipe" aria-label="左滑切换歌词" @touchstart="beginPlayerSwipe" @touchmove="movePlayerSwipe" @touchend="endPlayerSwipe" @touchcancel="cancelPlayerSwipe"></view>
        </view>
        <view class="player-dock glass-card">
          <view v-if="importBusy" class="player-import-status" role="status"><text>{{ importStatus }}</text><view><text>本首 {{ importFilePercent }}% · 总体 {{ importPercent }}% · {{ importElapsed }} 秒</text><button :disabled="importCancelled" @tap="cancelImport">{{ importCancelled ? '正在取消…' : '取消导入' }}</button></view><progress :percent="importPercent" activeColor="#5d896c" backgroundColor="#dce8df" :stroke-width="3" /></view>
          <text v-if="interruption" class="interruption-note" role="status">{{ interruption }}</text>
          <view v-if="lastError" class="playback-error"><text>{{ lastError }}</text><button @tap="playTrack(currentTrack, true)">重试</button></view>
          <view class="dock-title"><image v-if="currentTrack.cover" class="dock-art" :src="currentTrack.cover" mode="aspectFill" /><view><text class="track-title">{{ currentTrack.title }}</text><text class="track-artist">{{ currentTrack.artist || '未知歌手' }}</text></view><button class="favorite-button" :class="{ selected: currentTrack.favorite }" :aria-label="currentTrack.favorite ? '取消喜欢' : '喜欢这首歌'" @tap="toggleFavorite()"><image :src="currentTrack.favorite ? '/static/icons/heart-filled.svg' : '/static/icons/heart.svg'" mode="aspectFit" /></button></view>
          <slider class="seek-slider" :value="progress" :disabled="!duration" activeColor="#6b9f7c" backgroundColor="#dfe7e1" block-color="#6b9f7c" :block-size="16" @changing="previewSeek" @change="seekTo" />
          <view class="time-labels"><text>{{ formatTime(currentTime) }}</text><text>{{ formatTime(duration) }}</text></view>
          <view class="player-controls"><button class="mode-button" @tap="cycleMode">{{ modeLabel }}</button><button class="transport-button" aria-label="上一首" @tap="playAdjacent(-1)"><image src="/static/icons/previous.svg" mode="aspectFit" /></button><button class="play-main" :loading="loading" :aria-label="isPlaying ? '暂停' : '播放'" @tap="togglePlayback"><image v-if="!loading" :src="isPlaying ? '/static/icons/pause.svg' : '/static/icons/play.svg'" mode="aspectFit" /></button><button class="transport-button" aria-label="下一首" @tap="playAdjacent(1)"><image src="/static/icons/next.svg" mode="aspectFit" /></button><button class="mode-button" @tap="sheet = 'queue'">队列 {{ queueTracks.length }}</button></view>
          <button class="sleep-button" :class="{ selected: sleepUntil || sleepAfterTrack }" @tap="sheet = 'sleep'">{{ sleepLabel }}</button>
        </view>
      </view>
    </view>
    <view v-if="sheet" class="sheet-overlay" @tap.self="sheet = ''">
      <view class="action-sheet glass-card" role="dialog" aria-modal="true">
        <view class="sheet-header"><text>{{ sheetTitle }}</text><button class="text-button" aria-label="关闭面板" @tap="sheet = ''">关闭</button></view>
        <scroll-view class="sheet-scroll" scroll-y>
          <view v-if="sheet === 'track' && menuTrack" class="action-list">
            <text class="sheet-subtitle">{{ menuTrack.title }}</text>
            <button @tap="menuTrack.id === currentId ? togglePlayback() : playTrack(menuTrack); sheet = ''">{{ menuTrack.id === currentId && isPlaying ? '暂停播放' : '播放歌曲' }}</button>
            <button @tap="openTrack(menuTrack)">查看歌曲</button><button @tap="queueNext(menuTrack)">下一首播放</button>
            <button :disabled="!!repairingId || importBusy || backupBusy" @tap="repairEmbedded(menuTrack)">{{ repairingId === menuTrack.id ? '正在读取内嵌信息…' : '补全内嵌封面与歌词' }}</button>
            <button @tap="toggleFavorite(menuTrack); sheet = ''">{{ menuTrack.favorite ? '取消喜欢' : '加入喜欢' }}</button>
            <button @tap="sheet = 'add-playlist'">加入歌单</button><button @tap="editTrack(menuTrack)">编辑歌曲信息</button>
            <template v-if="menuTrack.id === currentId"><button @tap="sheet = ''; importCover()">更换封面</button><button @tap="sheet = ''; importLyrics()">导入歌词文件</button><button @tap="openLyricSearch">联网找歌词</button></template>
            <template v-if="libraryFilter === 'playlists' && groupFilter"><button :disabled="libraryTracks[0]?.id === menuTrack.id" @tap="movePlaylistTrack(menuTrack, -1)">在歌单中上移</button><button :disabled="libraryTracks[libraryTracks.length - 1]?.id === menuTrack.id" @tap="movePlaylistTrack(menuTrack, 1)">在歌单中下移</button></template>
            <button v-if="libraryFilter === 'playlists' && groupFilter" @tap="removeFromPlaylist(menuTrack)">从当前歌单移除</button>
            <button :disabled="!!relinkingId || importBusy || backupBusy" @tap="relinkTrack(menuTrack)">重新关联音频文件</button><text class="sheet-subtitle">移除会清理应用副本，保留手机原始文件。</text><button class="danger" @tap="removeTrack(menuTrack)">从音乐库移除</button>
          </view>
          <view v-if="sheet === 'details' && detailTrack" class="track-details">
            <image v-if="detailTrack.cover" class="detail-cover" :src="detailTrack.cover" mode="aspectFill" /><view v-else class="detail-cover cover-fallback">♫</view>
            <text class="detail-title">{{ detailTrack.title }}</text><text class="detail-meta">{{ detailTrack.artist || '未知歌手' }} · {{ detailTrack.album || '未知专辑' }}</text>
            <text class="detail-meta">{{ detailTrack.duration ? formatTime(detailTrack.duration) : '时长尚未读取' }} · {{ detailTrack.lyrics.length ? detailTrack.lyrics.length + ' 行歌词' : '暂无歌词' }}</text>
            <text class="sheet-subtitle">{{ detailTrack.cover ? '封面已就绪' : '缺少封面' }} · {{ detailTrack.lyrics.length ? '歌词已就绪' : '缺少歌词' }}</text><button class="secondary-button" :disabled="!!repairingId || importBusy || backupBusy" @tap="repairEmbedded(detailTrack)">{{ repairingId === detailTrack.id ? '正在读取…' : '从歌曲文件补全封面与歌词' }}</button><text class="sheet-subtitle">只补全缺失内容，保留你已设置的封面和歌词。</text>
            <text v-if="detailTrack.metadataPending" class="sheet-subtitle">正在排队补全封面与歌词，音频已可播放。</text>
            <text v-if="detailTrack.metadataError" class="sheet-subtitle">信息读取失败：{{ detailTrack.metadataError }}。可点击上方按钮重试。</text>
            <button v-if="detailTrack.missing" class="primary-button" :disabled="!!relinkingId || importBusy || backupBusy" @tap="relinkTrack(detailTrack)">{{ relinkingId ? '正在关联…' : '重新关联音频文件' }}</button>
            <text v-if="detailTrack.filenameGuess" class="sheet-subtitle">歌曲信息由文件名推测，请核对歌名与歌手。</text>
            <text class="sheet-subtitle">查看详情不会改变当前播放。</text>
            <button class="primary-button" @tap="playTrack(detailTrack); playerOpen = true; sheet = ''">播放这首歌</button><button class="text-button" @tap="editTrack(detailTrack)">编辑歌曲信息</button>
          </view>
          <view v-if="sheet === 'queue'">
            <view v-for="(track, index) in queueTracks.slice(0, queueLimit)" :key="track.id" class="queue-row" :class="{ selected: track.id === currentId }"><button class="queue-title" @tap="playTrack(track)">{{ track.title }}<text v-if="track.id === currentId"> · 当前</text></button><button :disabled="index === 0" aria-label="上移" @tap="moveQueue(index, -1)"><image src="/static/icons/arrow-up.svg" /></button><button :disabled="index === queueTracks.length - 1" aria-label="下移" @tap="moveQueue(index, 1)"><image src="/static/icons/arrow-down.svg" /></button><button :disabled="track.id === currentId" aria-label="移出队列" @tap="removeQueue(track.id)">移除</button></view>
            <button v-if="queueTracks.length > queueLimit" class="text-button" @tap="queueLimit += 60">继续加载队列（还有 {{ queueTracks.length - queueLimit }} 首）</button>
            <text v-if="!queueTracks.length" class="empty-copy">播放一首歌曲，即可建立队列。</text>
          </view>
          <view v-if="sheet === 'sleep'" class="action-list"><button v-for="minutes in [15, 30, 45, 60]" :key="minutes" @tap="setSleep(minutes)">{{ minutes }} 分钟后停止</button><button @tap="setSleep(-1)">本曲播放完停止</button><button @tap="setSleep(0)">关闭定时停止</button></view>
          <view v-if="sheet === 'edit' && editor" class="edit-form"><view class="info-inference"><button class="text-button" @tap="inferTrackInfo">从文件名填入</button><button class="text-button" @tap="[editor.title, editor.artist] = [editor.artist, editor.title]">交换歌名与歌手</button></view><text>歌名</text><input v-model="editor.title" maxlength="150" placeholder="歌名" /><text>歌手</text><input v-model="editor.artist" maxlength="150" placeholder="歌手" /><text>专辑</text><input v-model="editor.album" maxlength="150" placeholder="专辑" /><button class="primary-button" @tap="saveEdit">核对并保存</button></view>
          <view v-if="sheet === 'lyrics-search' && lyricSearch" class="edit-form lyrics-search-form">
            <text class="sheet-subtitle">搜索结果将用于「{{ tracks.find(track => track.id === lyricSearch.trackId)?.title || '已移除的歌曲' }}」。只发送歌曲信息，不上传音频。</text>
            <text>歌名</text><input v-model="lyricSearch.title" :disabled="lyricBusy" maxlength="150" placeholder="搜索歌词的歌名" confirm-type="search" @confirm="searchOnlineLyrics" />
            <text>歌手（可选）</text><input v-model="lyricSearch.artist" :disabled="lyricBusy" maxlength="150" placeholder="搜索歌词的歌手" confirm-type="search" @confirm="searchOnlineLyrics" />
            <button class="primary-button" :loading="lyricBusy" :disabled="lyricBusy || !lyricSearch.title.trim()" @tap="searchOnlineLyrics">{{ lyricBusy ? '正在寻找同步歌词' : '搜索同步歌词' }}</button>
            <text v-if="lyricMessage" class="lyrics-search-message" role="status">{{ lyricMessage }}</text>
            <text v-if="lyricResults.length" class="sheet-subtitle">找到 {{ lyricResults.length }} 个同步版本 · 本地音频 {{ lyricSearch.duration ? formatTime(lyricSearch.duration) : '时长未知' }}。选择与你的音频一致的版本。</text>
            <button v-for="candidate in lyricResults" :key="candidate.id" class="lyric-candidate" :disabled="backupBusy" @tap="lyricPreview = candidate">
              <view><text class="track-title">{{ candidate.title }}</text><text class="track-artist">{{ candidate.artist }} · {{ candidate.album || '未知专辑' }}</text><text class="candidate-detail">{{ formatTime(candidate.duration) }} · {{ candidate.lyrics.length }} 行 · {{ candidate.confident ? '匹配歌名、歌手与时长' : candidate.difference === null ? '请核对版本' : '时长相差 ' + candidate.difference.toFixed(1) + ' 秒' }}</text></view><text class="candidate-use">预览</text>
            </button>
            <view v-if="lyricPreview" class="lyric-preview-card">
              <text class="track-title">{{ lyricPreview.title }} · {{ lyricPreview.artist }}</text>
              <text v-for="(line, index) in lyricPreview.lyrics.slice(0, 8)" :key="index" class="lyric-preview-line">{{ formatTime(line.time) }}　{{ line.text || '♪' }}</text>
              <button class="primary-button" :disabled="backupBusy" @tap="applyOnlineLyrics(lyricPreview)">使用这个版本</button>
            </view>
            <text class="sheet-subtitle">保存后无需联网；已有歌词会在确认后替换。</text>
          </view>
          <view v-if="sheet === 'rename-playlist'" class="edit-form"><text>歌单名称</text><input v-model="playlistEditName" maxlength="60" placeholder="歌单名称" /><button class="primary-button" @tap="renamePlaylist">保存名称</button></view>
          <view v-if="sheet === 'add-playlist' || sheet === 'new-playlist'" class="edit-form">
          <view v-if="sheet === 'add-playlist'" class="action-list"><button v-for="list in playlists" :key="list.id" @tap="addToPlaylist(list)">{{ list.name }} · {{ list.trackIds.length }} 首</button></view>
            <text>新歌单</text><input v-model="playlistName" placeholder="输入歌单名称" maxlength="60" /><button class="primary-button" @tap="createPlaylist">{{ sheet === 'add-playlist' ? '创建并加入' : '创建歌单' }}</button>
          </view>
          <view v-if="sheet === 'settings'" class="action-list"><view class="lyrics-setting"><view><text>自动获取同步歌词</text><text class="sheet-subtitle">缺少同步歌词时，导入或首次播放后尝试匹配。仅发送歌名、歌手等信息给国内网易云歌词源。</text></view><switch :checked="autoLyrics" color="#6b9f7c" aria-label="自动获取同步歌词" @change="toggleAutoLyrics" /></view><text class="sheet-subtitle">备份包含音频、封面、歌词、歌单和视觉设置。恢复时合并到现有音乐库。</text><button :disabled="backupBusy || importBusy || !tracks.length" @tap="exportBackup">{{ backupBusy ? '正在处理…' : '导出完整备份' }}</button><view class="lyrics-setting"><text>恢复备份中的设置</text><switch :checked="restoreSettings" color="#6b9f7c" @change="restoreSettings = $event.detail.value" /></view><button :disabled="backupBusy || importBusy" @tap="chooseBackup">从备份恢复</button><button @tap="sheet = 'new-playlist'">新建歌单</button><button @tap="refreshDeviceStatus(); sheet = 'playback-help'">后台播放与系统控制</button><button v-if="failures.length" @tap="sheet = 'failures'">查看导入失败记录</button><text v-if="importStatus" class="sheet-subtitle">{{ importStatus }}</text></view>
          <view v-if="sheet === 'playback-help'" class="action-list"><text class="sheet-subtitle">当前{{ isPlaying ? '正在播放' : '已暂停' }} · {{ formatTime(currentTime) }} / {{ formatTime(duration) }}</text><text class="sheet-subtitle">应用退到后台仍可继续播放，粒子绘制会停止。耳机断开或播放被系统中断后，点击播放继续。</text><text class="sheet-subtitle">如锁屏后停止，请在系统设置中允许雾屿的通知和后台运行；不同品牌手机的省电策略不同。</text><text v-if="systemControlStatus" class="sheet-subtitle">{{ systemControlStatus }}</text><text class="sheet-subtitle">OPPO Find X8 / ColorOS 16：播放后上滑返回桌面，查看顶部音乐胶囊。若未显示，在系统设置中搜索“流体云”，检查音乐播放提示是否允许。</text><view v-if="deviceStatus.available" class="diagnostic-card">
            <text>{{ deviceStatus.brand }} {{ deviceStatus.model }} · Android {{ deviceStatus.android }}</text>
            <text>通知：{{ deviceStatus.notifications ? '已允许' : '未允许' }}</text><text>后台电池优化：{{ deviceStatus.batteryExempt ? '已豁免' : '受系统优化管理' }}</text>
            <text>省电模式：{{ deviceStatus.powerSave ? '开启' : '关闭' }} · 温度状态：{{ deviceStatus.thermal < 0 ? '系统未提供' : deviceStatus.thermal >= 3 ? '较高' : deviceStatus.thermal >= 2 ? '偏高' : '正常' }}</text>
            <button @tap="openSystemSettings('notifications')">通知设置</button><button @tap="openSystemSettings('battery')">后台电池设置</button><button @tap="openSystemSettings('app')">应用系统设置</button>
          </view><text v-else class="sheet-subtitle">{{ deviceStatus.message }}</text><button @tap="refreshDeviceStatus">刷新诊断</button><button @tap="copyPlaybackDiagnostics">复制诊断信息</button><text v-if="interruption" class="sheet-subtitle">{{ interruption }}</text><text v-if="lastError" class="sheet-subtitle">{{ lastError }}</text></view>
          <view v-if="sheet === 'failures'"><view v-for="(failure, index) in failures" :key="index" class="failure-row"><text>{{ failure.name }}</text><text>{{ failure.message }}</text></view><button class="primary-button" :disabled="importBusy || backupBusy" @tap="retryFailedImports">仅重试未成功的歌曲</button><button class="secondary-button" :disabled="importBusy" @tap="sheet = ''; importSong()">重新选择文件</button></view>
        </scroll-view>
      </view>
    </view>
  </view>
</template>

<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { onBackPress } from '@dcloudio/uni-app'
import TrackList from '../../components/TrackList.vue'
import LyricsLines from '../../components/LyricsLines.vue'
import ParticleCover from '../../components/ParticleCover.vue'
import ListeningDisplay from '../../components/ListeningDisplay.vue'
import { useMusic } from '../../utils/use-music.js'
import { swipePlayerView } from '../../utils/library-core.js'
const {
  movePlaylistTrack, metadataStatus, selecting, selectedIds, selectedTracks, endSelection, selectAllTracks, batchFavorite, removeSelected, playlistEditName, renamePlaylist, deviceStatus, refreshDeviceStatus, openSystemSettings, relinkingId, relinkTrack, restoreSettings,
  tracks, playlists, queueTracks, currentId, currentTrack, activeTab, playerOpen, playerView,
  query, libraryFilter, groupFilter, visibleTracks, libraryTracks, libraryGroups, isPlaying,
  loading, ready, importBusy, importStatus, currentTime, duration, activeLyric, followLyrics,
  progress, modeLabel, sleepLabel, sleepUntil, sleepAfterTrack, sheet,
  menuTrack, editor, playlistName, failures, lastError, backupBusy, importSong, importCover,
  importLyrics, selectTrack, openTrack, playTrack, togglePlayback, playAdjacent, cycleMode,
  previewSeek, seekTo, seekLyric, adjustOffset, setSleep, showTrackMenu, queueNext, moveQueue,
  removeQueue, toggleFavorite, editTrack, saveEdit, addToPlaylist, createPlaylist,
  removeFromPlaylist, deletePlaylist, removeTrack, exportBackup, chooseBackup, formatTime,
  setFilter, initialize,
  autoLyrics, toggleAutoLyrics, lyricSearch, lyricResults, lyricBusy, lyricMessage,
  openLyricSearch, searchOnlineLyrics, applyOnlineLyrics,
  detailTrack, inferTrackInfo, lyricFetching, lyricRetryable, retryCurrentLyrics, backupProgress, interruption,
  importPercent, importFilePercent, importFileElapsed, importElapsed, importCancelled, cancelImport, retryFailedImports, repairingId, repairEmbedded, appForeground, refreshPlaybackState, systemControlStatus,
} = useMusic()
const particleRef = ref(null), lyricPreview = ref(null)
watch(lyricResults, () => { lyricPreview.value = null })
watch(activeTab, endSelection)
function copyPlaybackDiagnostics() { uni.setClipboardData({ data: JSON.stringify({ device: deviceStatus.value, controls: systemControlStatus.value, playing: isPlaying.value, time: currentTime.value, duration: duration.value, interruption: interruption.value, error: lastError.value }, null, 2) }) }
const listeningDisplay = ref(false), listeningDisplayRef = ref(null)
const immersive = ref(false), immersiveExitVisible = ref(false)
let immersiveTimer
function revealImmersiveExit() { if (!immersive.value) return; immersiveExitVisible.value = true; clearTimeout(immersiveTimer); immersiveTimer = setTimeout(() => { immersiveExitVisible.value = false }, 2500) }
function enterListeningDisplay() { sheet.value = ''; playerView.value = 'cover'; immersive.value = false; listeningDisplay.value = true; cancelPlayerSwipe() }
function handleSceneTap() { if (listeningDisplay.value) listeningDisplayRef.value?.reveal(); else revealImmersiveExit() }
function enterImmersive() { listeningDisplay.value = false; sheet.value = ''; playerView.value = 'cover'; immersive.value = true; immersiveExitVisible.value = false; cancelPlayerSwipe() }
function immersiveEscape(event) { if (event.key === 'Escape') { if (listeningDisplay.value) listeningDisplay.value = false; else immersive.value = false } }
watch(playerOpen, open => { if (!open) { immersive.value = false; listeningDisplay.value = false } })
onMounted(() => {
  // #ifdef H5
  window.addEventListener('keydown', immersiveEscape)
  // #endif
})
onUnmounted(() => { clearTimeout(immersiveTimer);
  // #ifdef H5
  window.removeEventListener('keydown', immersiveEscape)
  // #endif
})
const pageScrollTop = ref(0), viewportTop = ref(60), viewportHeight = ref(600), queueLimit = ref(60)
const playerDrag = ref(0), playerSwiping = ref(false), playerWidth = ref(375)
const playerPanelStyle = computed(() => ({ transform: `translate3d(calc(${playerView.value === 'lyrics' ? '-50%' : '0%'} + ${playerDrag.value}px), 0, 0)` }))
let playerSwipe = null
let nextPlayerSwipeAt = 0
function cancelPlayerSwipe() { playerSwipe = null; playerSwiping.value = false; playerDrag.value = 0 }
function activateLyricAction() {
  if (lyricRetryable.value && !lyricFetching.value.includes(currentId.value)) retryCurrentLyrics()
  else openLyricSearch()
}
function beginPlayerSwipe(event) {
  const touches = event.touches || []
  if (touches.length !== 1 || sheet.value || Date.now() < nextPlayerSwipeAt) { cancelPlayerSwipe(); return }
  const touch = touches[0]
  playerSwipe = { id: touch.identifier, x: touch.clientX, y: touch.clientY, started: Date.now(), view: playerView.value, direction: '' }
}
function movePlayerSwipe(event) {
  if (!playerSwipe) return
  if (event.touches?.length !== 1) { cancelPlayerSwipe(); return }
  const touch = event.touches[0]
  if (touch.identifier !== playerSwipe.id) { cancelPlayerSwipe(); return }
  const dx = Math.abs(touch.clientX - playerSwipe.x), dy = Math.abs(touch.clientY - playerSwipe.y)
  if (!playerSwipe.direction && Math.max(dx, dy) >= 12) playerSwipe.direction = dx > dy * 1.5 ? 'horizontal' : 'vertical'
  if (playerSwipe.direction === 'horizontal') {
    playerSwiping.value = true
    const distance = touch.clientX - playerSwipe.x
    const allowed = playerSwipe.view === 'cover' ? distance < 0 : distance > 0
    playerDrag.value = Math.sign(distance) * Math.min(Math.abs(distance), playerWidth.value) * (allowed ? 1 : 0.15)
  }
}
function endPlayerSwipe(event) {
  const gesture = playerSwipe
  playerSwipe = null
  playerSwiping.value = false
  playerDrag.value = 0
  if (!gesture || event.touches?.length || sheet.value || gesture.view !== playerView.value) return
  const touch = Array.from(event.changedTouches || []).find(item => item.identifier === gesture.id)
  if (!touch) return
  const view = swipePlayerView(gesture.view, touch.clientX - gesture.x, touch.clientY - gesture.y, Date.now() - gesture.started, gesture.direction === 'vertical')
  if (view !== playerView.value) { playerView.value = view; if (view === 'lyrics') followLyrics.value = true }
}
watch([playerOpen, currentId, sheet], cancelPlayerSwipe)
watch(playerView, view => { nextPlayerSwipeAt = Date.now() + 280; if (view === 'lyrics') followLyrics.value = true })
let pageDisposed = false
async function measureViewport() {
  await nextTick()
  if (pageDisposed) return
  uni.createSelectorQuery().select('.page-scroll').boundingClientRect(rect => {
    if (rect && !pageDisposed) { viewportTop.value = rect.top; viewportHeight.value = rect.height }
  }).exec()
  uni.createSelectorQuery().select('.player-content').boundingClientRect(rect => {
    if (rect?.width && !pageDisposed) playerWidth.value = rect.width
  }).exec()
}
watch([activeTab, libraryFilter, groupFilter, importStatus, playerOpen, currentId], measureViewport, { flush: 'post' })
watch(sheet, () => { queueLimit.value = 60 })
onMounted(() => { measureViewport(); uni.onWindowResize(measureViewport) })
onUnmounted(() => { pageDisposed = true; uni.offWindowResize(measureViewport) })
const filters = [{ id: 'all', label: '歌曲' }, { id: 'favorites', label: '喜欢' }, { id: 'albums', label: '专辑' }, { id: 'artists', label: '歌手' }, { id: 'playlists', label: '歌单' }]
const tabs = [{ id: 'discover', label: '发现', icon: '/static/icons/home.svg' }, { id: 'search', label: '搜索', icon: '/static/icons/search.svg' }, { id: 'library', label: '音乐库', icon: '/static/icons/library.svg' }]
const sheetTitle = computed(() => ({ 'rename-playlist': '重命名歌单', track: '歌曲操作', details: '歌曲详情', queue: '播放队列', sleep: '定时停止', edit: '编辑歌曲信息', 'add-playlist': '加入歌单', 'new-playlist': '新建歌单', settings: '音乐库管理', 'playback-help': '后台播放', failures: '导入失败记录', 'lyrics-search': '联网找歌词' }[sheet.value] || ''))
onBackPress(() => {
  if (listeningDisplay.value) { listeningDisplay.value = false; return true }
  if (immersive.value) { immersive.value = false; return true }
  if (sheet.value) { sheet.value = ''; return true }
  if (playerOpen.value) { playerOpen.value = false; return true }
  return false
})
</script>

